// Shared between embedding.cpp and the bindings.cpp generated by main.rs
#pragma once

#include <cstddef>
#include <cstdint>
#include <cstdlib>

// provided by embedding.cpp

/// Calls the JS binding registered as export callback \p i
double call_export(size_t i, const double *args, size_t n);
/// Return area for a call; freed by post-return (exports) or by the bindings (imports)
int32_t alloc_ret(size_t size);
/// Frees the allocations made by JS lowering, once the host is done with them
void free_tracked();

// provided by bindings.cpp

extern const size_t EXPORT_COUNT;
/// Calls core import \p i with the arguments the JS binding passed
double call_import(size_t i, const double *args);
/// Calls the [resource-new], [resource-rep] or [resource-drop] import \p i
double call_resource(size_t i, int32_t handle);
